mapper.select:
SELECT mcp.*, mcpd.id AS detail_id, mcpd.create_time AS detail_create_time, mcpd.update_time AS detail_update_time, mcpd.bool_delete_enum AS detail_bool_delete_enum, mcpd.version AS detail_version, mcpd.coating_process_id AS detail_coating_process_id, mcpd.paint_type AS detail_paint_type, mcpd.paint_brand AS detail_paint_brand, mcpd.paint_category AS detail_paint_category, mcpd.thickness AS detail_thickness, mcpd.remark AS detail_remark, mcpd.use_quantity AS detail_use_quantity, su.name AS create_user_name, cp.short_name AS contract_project_short_name, cp.serial_number AS contract_project_serial_number FROM mes_coating_process mcp LEFT JOIN mes_coating_process_detail mcpd ON mcpd.bool_delete_enum = FALSE AND mcpd.coating_process_id = mcp.id LEFT JOIN sys_user su ON su.id = mcp.create_user_id LEFT JOIN contract_project cp ON cp.id = mcp.contract_project_id WHERE mcp.bool_delete_enum = FALSE
AND mcp.contract_project_id IN (
#{i}
)

SELECT t.*, ssc.classification_name AS artifact_type_name, IFNULL(t1.associated_quantity, 0) AS associated_quantity, IFNULL(t2.operable_quantity, 0) as operable_quantity FROM ( SELECT ta.structure_class_id AS artifact_type_id, COUNT(ta.structure_class_id) AS list_quantity FROM tech_artifact ta WHERE ta.bool_delete_enum = FALSE
AND ta.project_id = #{projectId}
AND ta.monomer_id = #{monomerId}
AND ta.area_id = #{areaId}
GROUP BY ta.structure_class_id ) t LEFT JOIN ( SELECT st.structure_class_id, COUNT(st.artifact_id) AS associated_quantity FROM ( SELECT sta.structure_class_id, stae.artifact_id FROM tech_artifact_ext stae LEFT JOIN tech_artifact sta ON sta.id = stae.artifact_id WHERE stae.bool_delete_enum = FALSE AND stae.boolean_painting = TRUE
AND stae.project_id = #{projectId}
AND stae.monomer_id = #{monomerId}
AND stae.area_id = #{areaId}
GROUP BY sta.structure_class_id, stae.artifact_id ) st GROUP BY st.structure_class_id ) t1 ON t1.structure_class_id = t.artifact_type_id LEFT JOIN ( SELECT st.structure_class_id, sum(st.operable_quantity) AS operable_quantity FROM ( SELECT sta.structure_class_id, stae.artifact_id, sum(ifnull(stae.quantity, 0)) as operable_quantity FROM tech_artifact_ext stae LEFT JOIN tech_artifact sta ON sta.id = stae.artifact_id WHERE stae.bool_delete_enum = FALSE AND stae.boolean_painting IS NULL
AND stae.project_id = #{projectId}
AND stae.monomer_id = #{monomerId}
AND stae.area_id = #{areaId}
GROUP BY sta.structure_class_id, stae.artifact_id ) st GROUP BY st.structure_class_id ) t2 ON t2.structure_class_id = t.artifact_type_id LEFT JOIN sys_structure_classification ssc ON ssc.bool_delete_enum = FALSE AND ssc.id = t.artifact_type_id

SELECT ta.id, ta.create_time, ta.update_time, ta.bool_delete_enum, ta.version, ta.project_id, ta.monomer_id, ta.area_id, ta.old_artifact_id, ta.old_artifact_serial_number, ta.bool_status_enum, ta.bool_abnormal_enum, ta.name, ta.serial_number, ta.specification, ta.length, ta.material, ta.net_weight, ta.total_net_weight, ta.gross_weight, ta.total_gross_weight, ta.surface_area, ta.drawing_number, ta.remark, ta.user_id, ta.business_id, ta.produced_quantity, ta.area_type, ta.spec_prefix, ta.smart_line_mark_word, ta.artifact_type, ta.bool_coating_enum, ta.bool_scheduling_enum, ta.coding_type, ta.structure_class_id, ta.bool_single_part_enum, ta.purchase_quantity, ta.bool_all_part_send_directly, ta.bool_send_directly, ta.building_type, ta.drawing_weight, ta.drawing_total_weight, ta.serial_number_prefix, cp.name AS project_name, pm.name AS monomer_name, pa.name AS area_name, t1.quantity FROM tech_artifact ta INNER JOIN ( SELECT taext.artifact_id, SUM(IFNULL(taext.quantity, 0)) AS quantity FROM tech_artifact_ext taext WHERE taext.bool_delete_enum = FALSE AND taext.boolean_painting IS NULL GROUP BY taext.artifact_id ) t1 ON t1.artifact_id = ta.id LEFT JOIN contract_project cp ON cp.id = ta.project_id LEFT JOIN plan_monomer pm ON pm.id = ta.monomer_id LEFT JOIN plan_area pa ON pa.id = ta.area_id WHERE ta.bool_delete_enum = FALSE
AND ta.project_id = #{projectId}
AND ta.monomer_id = #{monomerId}
AND ta.area_id = #{areaId}
AND ta.structure_class_id = #{artifactTypeId}
AND ta.name LIKE #{nameLike}
AND ta.serial_number LIKE #{serialNumberLike}
AND ta.specification LIKE #{specificationLike}
AND ta.material LIKE #{material}

SELECT ta.id, ta.create_time, ta.update_time, ta.bool_delete_enum, ta.version, ta.project_id, ta.monomer_id, ta.area_id, ta.old_artifact_id, ta.old_artifact_serial_number, ta.bool_status_enum, ta.bool_abnormal_enum, ta.name, ta.serial_number, ta.specification, ta.length, ta.material, ta.net_weight, ta.total_net_weight, ta.gross_weight, ta.total_gross_weight, ta.drawing_number, ta.remark, ta.user_id, ta.business_id, ta.produced_quantity, ta.area_type, ta.spec_prefix, ta.smart_line_mark_word, ta.artifact_type, ta.bool_coating_enum, ta.bool_scheduling_enum, ta.coding_type, ta.structure_class_id, ta.bool_single_part_enum, ta.purchase_quantity, ta.bool_all_part_send_directly, ta.bool_send_directly, ta.building_type, ta.drawing_weight, ta.drawing_total_weight, ta.serial_number_prefix, cp.name AS project_name, pm.name AS monomer_name, pa.name AS area_name, t1.quantity, t1.area AS surface_area FROM ( SELECT taext.artifact_id, taext.area, SUM(IFNULL(taext.quantity, 0)) AS quantity FROM tech_artifact_ext taext WHERE taext.bool_delete_enum = FALSE AND taext.boolean_painting IS NOT NULL
AND taext.coating_process_id = #{id}
GROUP BY taext.artifact_id, taext.area ) t1 LEFT JOIN tech_artifact ta ON ta.id = t1.artifact_id LEFT JOIN contract_project cp ON cp.id = ta.project_id LEFT JOIN plan_monomer pm ON pm.id = ta.monomer_id LEFT JOIN plan_area pa ON pa.id = ta.area_id
AND ta.name LIKE #{nameLike}
AND ta.serial_number LIKE #{serialNumberLike}
AND ta.specification LIKE #{specificationLike}
AND ta.material LIKE #{material}

SELECT taext.id, ta.project_id, ta.monomer_id, ta.area_id, ta.name, ta.serial_number, ta.specification, ta.length, ta.material, cp.name AS project_name, pm.name AS monomer_name, pa.name AS area_name, taext.quantity, taext.area AS surface_area, taext.bool_task, taext.sort_number FROM tech_artifact_ext taext LEFT JOIN tech_artifact ta ON ta.id = taext.artifact_id LEFT JOIN contract_project cp ON cp.id = ta.project_id LEFT JOIN plan_monomer pm ON pm.id = ta.monomer_id LEFT JOIN plan_area pa ON pa.id = ta.area_id WHERE taext.bool_delete_enum = FALSE
AND taext.coating_process_id = #{id} AND taext.boolean_painting = true
AND taext.artifact_id = #{artifactId}
AND taext.area = #{area}
AND taext.bool_task = #{boolProduced}
